  /// [(name, tones)] for "pill" or "notch".
  static func list(_ kind: String) -> [(String, [String: Any])] {
    guard let d = try? JSONSerialization.jsonObject(with: Data(json.utf8)) as? [String: Any], let a = d[kind] as? [[Any]] else { return [] }
    return a.compactMap { x in
      guard x.count == 2, let n = x[0] as? String, let t = x[1] as? [String: Any] else { return nil }
      return (n, t)
    }
  }
